$tests=0;$failures=0;$owned=array();
function ae_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function ae_assert($v,$message='Assertion failed'){if(!$v)throw new RuntimeException($message);}
function ae_fixture(){return N::validate(json_decode(file_get_contents(__DIR__.'/assessment-editor/fixture.json'),true));}
function ae_reject($fn,$code=null){try{$fn();}catch(Throwable $e){if($code!==null)ae_assert($e->getCode()===$code,'Unexpected rejection '.$e->getMessage());return;}throw new RuntimeException('Expected rejection');}
function ae_http($op,$data=array(),$nonce=true,$authenticated=true){return m0_http('/wp-admin/admin-ajax.php',array_merge(array('action'=>'eipsi_assessment_editor','nonce'=>$nonce?m0_admin_nonce('eipsi_native_assessment'):'bad','operation'=>$op),$data),$authenticated);}
