ae_test('server rejects duplicate element option and response identities',function(){foreach(array('element','option','response') as $case){$d=ae_fixture();if($case==='element')$d['elements'][1]['id']=$d['elements'][0]['id'];elseif($case==='response')$d['elements'][1]['response_key']=$d['elements'][0]['response_key'];else $d['elements'][1]['options'][1]['id']=$d['elements'][1]['options'][0]['id'];ae_reject(function()use($d){N::validate($d);});}});
ae_test('children and malformed PageBreak fail closed',function(){foreach(array('children','nested','properties') as $case){$d=ae_fixture();$pb=array_values(array_filter($d['elements'],static function($e){return $e['type']==='page_break';}))[0];if($case==='children')$d['elements'][0]['children']=array($pb);elseif($case==='nested'){$d['elements']=array_values(array_filter($d['elements'],static function($e){return $e['type']!=='page_break';}));foreach($d['elements'] as &$g)if($g['type']==='group')$g['children'][]=$pb;unset($g);}else$d['elements'][count($d['elements'])-1]['properties']['target']='illegal';ae_reject(function()use($d){N::validate($d);});}});
ae_test('required properties option structure and ordered list enforced',function(){foreach(array('required','option','list') as $case){$d=ae_fixture();if($case==='required')$d['elements'][0]['properties']['required']='yes';elseif($case==='option')unset($d['elements'][1]['options'][0]['label']);else$d['elements']=array('not-a-list'=>$d['elements'][0]);ae_reject(function()use($d){N::validate($d);});}});
ae_test('VAS bounds step initial and grid alignment validated',function(){foreach(array(array('min',100),array('step',0),array('step',3),array('initial',101),array('initial',51),array('max','100')) as $bad){$d=ae_fixture();foreach($d['elements'] as &$e)if($e['type']==='vas')$e['properties'][$bad[0]]=$bad[1];unset($e);ae_reject(function()use($d){N::validate($d);});}});
