ae_test('roundtrip save load serialize map serialize preserves all authored structure',function()use(&$owned){$d=ae_supported();$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];R::save($d,0);$loaded=R::load($d['id'])['definition'];$native=N::json($loaded);$mapped=M::map(json_decode($native,true));$serialized=$mapped->normalizedJson();$again=new \EIPSI\StudyEngine\Contracts\StudyVersionDefinition(json_decode($serialized,true));ae_assert($again->normalizedJson()===$serialized);ae_assert(N::json($again->toArray()['protocol_metadata']['native_definition'])===$native);$nodes=$again->toArray()['nodes'];$by=array_column($nodes,null,'id');$walk=function($items,$parent)use(&$walk,$by){foreach($items as $position=>$e){$node=$by[$e['id']];ae_assert($node['parent_id']===$parent&&$node['position']===$position);if($e['type']==='group'){$walk($e['children'],$e['id']);ae_assert(N::json($node['metadata']['native_element'])===N::json($e));}elseif($e['type']==='page_break')ae_assert($node['directive_kind']==='PAGE_BREAK');else{ae_assert(N::json(json_decode($node['content']['snapshot'],true)['native_element'])===N::json($e));if($e['response_key'])ae_assert($node['response_key']===$e['response_key']);}}};$walk($loaded['elements'],'A_'.$d['id']);});
